pub fn native_callback(part: PartDefinition, slot: CallbackSlot) -> Option<NativeCallback> {
    let index = match slot {
        CallbackSlot::CollisionResponse => 0,
        CallbackSlot::Update => 1,
        CallbackSlot::InitializeGeometry => 2,
        CallbackSlot::RopeContact => 3,
    };
    CALLBACKS[part.id() as usize][index]
}
